class Solution {
    private long getSum(long peak, long length) {
        if (length == 0) return 0;
        if (peak >= length) {
            return (2 * peak - length + 1) * length / 2;
        }
        return (peak + 1) * peak / 2 + (length - peak);
    }

    public int maxValue(int n, int targetIdx, int maxSum) {
        long low = 1, high = maxSum;
        int ans = 1;
        while (low <= high) {
            long mid = low + (high - low) / 2;
            long leftLen = targetIdx;
            long rightLen = n - 1 - targetIdx;
            long total = mid + getSum(mid - 1, leftLen) + getSum(mid - 1, rightLen);
            if (total <= maxSum) {
                ans = (int)mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
}

var maxValue = function(n, target_idx, max_sum) {
    function getSum(peak, length) {
        if (length === 0) return 0n;
        if (peak >= length) {
            return (2n * peak - length + 1n) * length / 2n;
        }
        return (peak + 1n) * peak / 2n + (length - peak);
    }
    let low = 1n, high = BigInt(max_sum);
    let ans = 1;
    while (low <= high) {
        const mid = (low + high) / 2n;
        const leftLen = BigInt(target_idx);
        const rightLen = BigInt(n - 1 - target_idx);
        const total = mid + getSum(mid - 1n, leftLen) + getSum(mid - 1n, rightLen);
        if (total <= BigInt(max_sum)) {
            ans = Number(mid);
            low = mid + 1n;
        } else {
            high = mid - 1n;
        }
    }
    return ans;
};
